const PANF=`uniform vec3 c,ce;uniform float gx,gy,lt;void main(){vec3 N=normalize(vN),V=normalize(vV),L=normalize(vec3(.5,.7,.5));if(!gl_FrontFacing)N=-N;float d=max(dot(N,L),0.),f=pow(1.-abs(dot(N,V)),2.);vec2 q=vU*vec2(gx,gy);vec2 gq=abs(fract(q)-.5);float seam=smoothstep(.46,.5,max(gq.x,gq.y));vec2 id=floor(q);float pv=h(vec3(id,1.));vec3 base=c*(.7+.4*pv)*(1.-seam*.6);float win=step(.86,h(vec3(id,3.)))*(.6+.4*sin(t*2.+pv*30.))*lt;vec3 col=base*(.12+.9*d)+pow(max(dot(reflect(-L,N),V),0.),40.)*.6*(1.-seam)+ce*win*1.6+ce*f*.15;gl_FragColor=vec4(col,1.);}`;
