const LANDF=`uniform float sc;void main(){vec3 N=normalize(vN),L=normalize(vec3(.5,.7,.5));if(!gl_FrontFacing)N=-N;float d=.4+.6*max(dot(N,L),0.);float h2=fbm(vP*sc);vec3 col=h2<.45?mix(vec3(.05,.15,.4),vec3(.1,.35,.6),h2/.45):mix(vec3(.2,.45,.15),vec3(.55,.5,.35),smoothstep(.5,.75,h2));col=mix(col,vec3(.9),smoothstep(.72,.8,h2));col*=.6+.5*fbm(vP*sc*5.);float cl=smoothstep(.55,.7,fbm(vP*sc*1.7+vec3(t*.02)));col=mix(col,vec3(.95),cl*.55);gl_FragColor=vec4(col*d,1.);}`;
const land=sc=>sm(LANDF,{sc:{value:sc||2}},{side:THREE.DoubleSide});
const CIRCF=`uniform vec3 c;void main(){vec3 N=normalize(vN),V=normalize(vV);float f=pow(1.-abs(dot(N,V)),2.);vec2 q=vU*vec2(90.,45.);vec2 id=floor(q),gq=fract(q);float hz=step(.5,h(vec3(id,1.)));float ln=hz>.5?smoothstep(.1,0.,abs(gq.y-.5)):smoothstep(.1,0.,abs(gq.x-.5));float on=step(.5,h(vec3(id,2.)));float pu=pow(fract(h(vec3(id,3.))+t*.5),12.);gl_FragColor=vec4(vec3(.03,.04,.07)+c*ln*on*(.3+pu*2.2)+c*f*.45,1.);}`;
