const MG={on:false};const mgTarget=()=>Math.round(52+Math.min(18,S.up.filter(id=>NODES[id]&&NODES[id].br==1).length*.4));
function openDyson(){if(MG.on||CS.on)return;MG.on=true;const ov=document.createElement('div');ov.id='mgov';ov.innerHTML='<div id="mgh"></div><canvas id="mgc"></canvas><div id="mgb"></div>';document.body.appendChild(ov);
const cv=$('mgc'),cx=cv.getContext('2d');let W=0,H=0,dpr=Math.min(devicePixelRatio,2);const size=()=>{const s=Math.min(innerWidth-20,innerHeight*.66,640);cv.style.width=cv.style.height=s+'px';cv.width=cv.height=s*dpr;W=H=cv.width};size();
const RINGS=[{R:.3,n:12,sp:.55,eff:1,life:7,col:'#ffd27a'},{R:.56,n:16,sp:-.32,eff:.75,life:14,col:'#9ad8ff'},{R:.82,n:20,sp:.16,eff:.5,life:1e9,col:'#c8a0ff'}];
let st='intro',T=40,t=0,acc=0,sup=3,fl=null,nextFl=4,raf=0,last=0;RINGS.forEach(r=>{r.a=0;r.p=new Array(r.n).fill(0)});const BINS=120;
const tgt=mgTarget(),ui=html=>{$('mgb').innerHTML=html};const head=()=>{$('mgh').innerHTML=st=='play'?`<b>Dyson Builder</b> · ${Math.ceil(T-t)}s · panels ${Math.floor(sup)} · energy ${(t>0?acc/t*100:0).toFixed(1)}% <small>(target ${tgt}%)</small>`:'<b>Dyson Builder</b>'};
const secAt=(r,a)=>{const w=6.2832/r.n;let x=((a-r.a)%6.2832+6.2832)%6.2832;return Math.floor(x/w)};
const cover=()=>{let e=0;for(let b=0;b<BINS;b++){const a=(b+.5)/BINS*6.2832;for(const r of RINGS){if(r.p[secAt(r,a)]>0){e+=r.eff;break}}}return e/BINS};
const intro=()=>{st='intro';head();ui(`<p>Tap a ring sector to place a collector panel. Panels block light for everything behind them, so the <b>inner ring</b> (100% efficient) matters most, but its panels burn out after 7s. The middle ring is 75% efficient and lasts 14s; the outer ring is 50% and permanent. Solar flares (red wedge) destroy inner and middle panels in their path.</p><p>Keep average captured energy above <b>${tgt}%</b> for 40 seconds${S.mg[1]?' (already passed: replays pay stardust on a cooldown)':' to unlock the <b>Cosmogenesis Engine</b>'}.</p><button id="mgs">Start</button> <button id="mgx">Close</button>`);$('mgs').onclick=start;$('mgx').onclick=close};
const start=()=>{st='play';t=0;acc=0;sup=3;fl=null;nextFl=4;RINGS.forEach(r=>{r.a=Math.random()*6;r.p.fill(0)});ui('<button id="mgx">Quit</button>');$('mgx').onclick=intro};
const finish=()=>{st='end';const sc=acc/T*100,pass=sc>=tgt;let msg='';if(pass&&!S.mg[1]){S.mg[1]=true;msg='<p style="color:#8fe39a">Passed! The Cosmogenesis Engine can now be rolled.</p>'}else if(pass)msg='<p style="color:#8fe39a">Passed.</p>';else msg=`<p style="color:#ff9a9a">${tgt}% needed. Try again.</p>`;
const now=Date.now();let rw='';if((S.mgc[1]||0)+600e3<now){const g2=income()*60*Math.max(.2,sc/100);S.coins+=g2;S.mgc[1]=now;rw=`<p>Reward: +${fmt(g2)} stardust</p>`}else rw=`<p><small>Reward on cooldown for ${Math.ceil(((S.mgc[1]+600e3)-now)/60e3)} min</small></p>`;
head();ui(`<p>Average energy: <b>${sc.toFixed(1)}%</b></p>${msg}${rw}<button id="mgs">Play again</button> <button id="mgx">Close</button>`);$('mgs').onclick=start;$('mgx').onclick=close};
const close=()=>{MG.on=false;cancelAnimationFrame(raf);ov.remove()};
cv.addEventListener('pointerdown',e=>{if(st!='play')return;const b=cv.getBoundingClientRect(),x=(e.clientX-b.left)/b.width*2-1,y=(e.clientY-b.top)/b.height*2-1,rr=Math.hypot(x,y),a=Math.atan2(y,x);let best=null,bd=.09;RINGS.forEach(r=>{const d=Math.abs(rr-r.R);if(d<bd){bd=d;best=r}});if(!best||sup<1)return;const k=secAt(best,a);if(best.p[k]<=0){best.p[k]=best.life;sup-=1}});
const draw=()=>{cx.clearRect(0,0,W,H);const c=W/2,s=W/2;const gr=cx.createRadialGradient(c,c,0,c,c,s*.2);gr.addColorStop(0,'#fff');gr.addColorStop(.4,'#ffd27a');gr.addColorStop(1,'rgba(255,160,60,0)');cx.fillStyle=gr;cx.beginPath();cx.arc(c,c,s*.2,0,6.29);cx.fill();
if(fl){cx.fillStyle=fl.hit?'rgba(255,80,60,.55)':`rgba(255,60,60,${.12+.12*Math.sin(t*20)})`;cx.beginPath();cx.moveTo(c,c);cx.arc(c,c,s*.95,fl.a-fl.w/2,fl.a+fl.w/2);cx.fill()}
RINGS.forEach(r=>{cx.strokeStyle='rgba(160,180,255,.18)';cx.lineWidth=s*.07;cx.beginPath();cx.arc(c,c,r.R*s,0,6.29);cx.stroke();const w=6.2832/r.n;for(let k=0;k<r.n;k++){if(r.p[k]<=0)continue;const lf=r.life<1e8?r.p[k]/r.life:1;cx.strokeStyle=r.col;cx.globalAlpha=.35+.65*lf;cx.lineWidth=s*.06;cx.beginPath();cx.arc(c,c,r.R*s,r.a+k*w+.03,r.a+(k+1)*w-.03);cx.stroke();cx.globalAlpha=1}});
for(let b=0;b<BINS;b+=2){const a=(b+.5)/BINS*6.2832;let hitR=1;for(const r of RINGS){if(r.p[secAt(r,a)]>0){hitR=r.R;break}}if(hitR>=1){cx.strokeStyle='rgba(255,230,160,.08)';cx.lineWidth=1;cx.beginPath();cx.moveTo(c+Math.cos(a)*s*.2,c+Math.sin(a)*s*.2);cx.lineTo(c+Math.cos(a)*s,c+Math.sin(a)*s);cx.stroke()}}};
const loop=now=>{raf=requestAnimationFrame(loop);const dt=Math.min(.05,(now-(last||now))/1000);last=now;if(st=='play'){t+=dt;sup=Math.min(6,sup+dt/.55);RINGS.forEach(r=>{r.a+=r.sp*dt;if(r.life<1e8)for(let k=0;k<r.n;k++)if(r.p[k]>0)r.p[k]-=dt});
nextFl-=dt;if(!fl&&nextFl<0)fl={a:Math.random()*6.2832,w:.55+Math.random()*.4,tt:1.2,hit:false};if(fl){fl.tt-=dt;if(fl.tt<0&&!fl.hit){fl.hit=true;fl.tt=.3;RINGS.slice(0,2).forEach(r=>{for(let k=0;k<r.n;k++){const mid=r.a+(k+.5)*6.2832/r.n;let d=Math.abs(((mid-fl.a)%6.2832+9.4248)%6.2832-3.1416);if(d<fl.w/2+.1)r.p[k]=0}})}else if(fl.hit&&fl.tt<0){fl=null;nextFl=2.5+Math.random()*2.5}}
acc+=cover()*dt;if(t>=T)finish();head()}draw()};intro();raf=requestAnimationFrame(loop)}
/* ---------- rebirth, shop, UI ---------- */
const rbGain=()=>30*((S.rb||0)+1)+Math.floor(cnt()/4)+3*echoCount();
const canRebirth=()=>S.own[LFIN[Math.min(S.rb,MAXRB)]]>-2;
function hideP(){['cxp','svp','rbp','shp'].forEach(id=>{const e=$(id);if(e)e.style.display='none'})}
function openRebirth(){hideP();const p=$('rbp');p.style.display='block';const nx=S.rb+1;if(nx>MAXRB){p.innerHTML=`<b>Beyond ${LNAME[S.rb]}</b><p>You've reached the edge of what exists so far: Layer ${ROMAN(nx)} (${LNAME[nx]}) is still being built.</p><button id="rbc">Close</button>`;$('rbc').onclick=hideP;return}
let sel=S.cst||'bal';const draw=()=>{p.innerHTML=`<b>Rebirth ${ROMAN(nx)}: ${LNAME[nx]}</b><p>Collapse this universe into a new one. You gain <b>${rbGain()} aether</b> (30×${nx} for the layer, +1 per 4 discoveries, +3 per Echo).</p>
<p><b>Kept:</b> codex (every model and every modifier ever seen), aether, shop upgrades, minigame progress.<br><b>Reset:</b> stardust, skill tree, collection, rolls, auto-roll${S.shop.auto?' (restored by Inherited Automation)':''}.</p>
<p><b>New:</b> Layer ${ROMAN(nx)} items up to 1 in 10^${LCAP[nx]}, Echo variants of earlier items, the Reborn modifier, 6 more nodes per skill branch, and the Dyson Builder minigame.</p><p><b>Physical constants for the next universe:</b></p><div id="rbk">${Object.entries(CONSTS).map(([k,c])=>`<button data-k="${k}" class="${k==sel?'on':''}" style="display:block;width:100%;text-align:left;margin:4px 0">${c.n}<br><small>${c.d}</small></button>`).join('')}</div>
<p><button id="rbgo" style="background:linear-gradient(135deg,#ff7a3a,#a24bff);border:0;font-weight:700">Rebirth</button> <button id="rbc">Cancel</button></p>`;
$('rbk').onclick=e=>{const b=e.target.closest('button');if(b){sel=b.dataset.k;draw()}};$('rbc').onclick=hideP;$('rbgo').onclick=()=>{hideP();doRebirth(sel)}};draw()}
function doRebirth(cst){ensureS();const gain=rbGain();S.rc+=gain;S.rb+=1;S.cst=cst||'bal';S.life.runs=(S.life.runs||0)+1;S.life.rolls=(S.life.rolls||0)+S.rolls;
S.own=new Array(N).fill(-2);S.cn=new Array(N).fill(0);S.ec=new Array(N).fill(0);S.up=[];S.rolls=0;S.coins=S.shop.head?Math.pow(10,3*S.shop.head):0;S.auto=!!S.shop.auto;if(S.shop.auto)S.ab=true;
recalc();NODES.forEach(n=>n.g=0);sel=-1;show(0,-1);refreshCodex();playRaw('bang',{n:'Rebirth '+ROMAN(S.rb),sub:LNAME[S.rb]+' · +'+gain+' aether',k:0,i:-1});toast('Rebirth '+ROMAN(S.rb)+': +'+gain+' aether')}
function openShop(){hideP();const p=$('shp');p.style.display='block';const draw=()=>{p.innerHTML=`<b>Aether shop</b> <small>${S.rc} aether · permanent across rebirths</small><div style="margin-top:8px">${SHOP.map(u=>{const l=S.shop[u.k]||0,mx=l>=u.max,c=shopCost(u,l);return`<div class="it" style="cursor:default"><div class="row"><span>${u.n} <small>lv ${l}/${u.max}</small></span><button data-k="${u.k}" ${mx||S.rc<c?'disabled':''} style="min-height:36px;padding:4px 10px">${mx?'Max':c+' ✦'}</button></div><div class="d">${u.d}</div></div>`}).join('')}</div><p><button id="shc">Close</button></p>`;
p.querySelectorAll('button[data-k]').forEach(b=>b.onclick=()=>{const u=SHOP.find(x=>x.k==b.dataset.k),l=S.shop[u.k]||0,c=shopCost(u,l);if(l<u.max&&S.rc>=c){S.rc-=c;S.shop[u.k]=l+1;if(u.k=='auto'){S.auto=true;S.ab=true}recalc();draw()}});$('shc').onclick=hideP};draw()}
function shopGreedy(){let b=true;while(b){b=false;let best=null;SHOP.forEach(u=>{const l=S.shop[u.k]||0;if(l<u.max){const c=shopCost(u,l);if(c<=S.rc&&(!best||c<best.c))best={u,c,l}}});if(best){S.rc-=best.c;S.shop[best.u.k]=best.l+1;if(best.u.k=='auto'){S.auto=true;S.ab=true}b=true}}recalc()}
